let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ru';
const isOzon=location.pathname.endsWith('ozon.html');
const isIvi=location.pathname.endsWith("ivi.html");
const isCase=isIvi||isOzon||location.pathname.endsWith('finelo.html');
function keepPrepositions(text){
  const words=lang==='ru'?'а|без|в|во|для|до|за|и|из|из-за|из-под|или|к|ко|между|на|над|не|но|о|об|обо|от|перед|по|под|при|про|с|со|у|через':'a|an|the|at|by|for|from|in|of|on|to|with';
  const shortWord=new RegExp(`(^|[\\s(«„“])(${words})[ \t]+(?=\\S)`,'giu');
  return text.split(/(<[^>]*>)/g).map(part=>part.startsWith('<')?part:part.replace(shortWord,'$1$2\u00a0').replace(shortWord,'$1$2\u00a0')).join('');
}
const t=(ru,en)=>keepPrepositions(lang==='ru'?ru:en);
const href=(page,hash='')=>`${page}?lang=${lang}&v=42${hash}`;
const externalArrow=`<svg class="external-arrow" viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M3 25 25 3M19 3h6v6"/></svg>`;
const external=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ${externalArrow}</a>`;
const ozonChrome=()=>`<span class="screen-chrome screen-status"><img src="assets/ozon-status.png?v=25" alt=""></span><span class="screen-chrome screen-tabbar"><img src="assets/ozon-tabbar.png?v=25" alt=""></span>`;
const ozonVectorPreviews=new Set(['ozon-search-start','ozon-search-category']);
const ozonPreviewCrops={'ozon-home':[0,670],'ozon-search':[0],'ozon-item':[0],'ozon-outfit':[0],'ozon-brands':[0],'ozon-brand':[0],'ozon-brand-products':[0],'ozon-proto-main':[718],'ozon-proto-category-view':[0]};
const hasOzonThumbnail=(name,options)=>options.crop&&ozonPreviewCrops[name]?.includes(Math.round((options.cropOffset||0)*874));
const ozonImageSource=(name,options)=>hasOzonThumbnail(name,options)?`assets/${name}-preview-${Math.round((options.cropOffset||0)*874)}.png?v=25`:ozonVectorPreviews.has(name)?`assets/${name}.svg?v=25`:`assets/${name}.png${name==='tools'?'?v=10':name.startsWith('ozon-')?'?v=25':''}`;
const screen=(name,ru,en,options={})=>`<button class="screen" data-image="${name}" ${name.startsWith('ozon-')?`data-full-src="assets/${name}.png?v=25"`:''} data-caption="${t(ru,en)}" ${options.component?'data-component="true"':''} ${options.chrome?'data-chrome="true"':''} data-crop-offset="${options.cropOffset||0}" ${options.crop?`data-crop="true" data-crop-ratio="${options.cropRatio||375/812}"`:''} ${options.mask?`data-skeleton-mask="${options.mask}"`:''} aria-label="${t('Увеличить: ','Enlarge: ')+t(ru,en)}"><span class="screen-surface ${options.component?'component-surface':''} ${options.crop?'is-cropped':''} ${hasOzonThumbnail(name,options)?'has-thumbnail':''}" style="${options.crop?`--screen-ratio:${options.cropRatio||375/812};--crop-offset:${options.cropOffset||0};`:''}${options.mask?`--skeleton-mask:url(assets/${options.mask})`:''}"><img src="${ozonImageSource(name,options)}" alt="${t(ru,en)}" loading="lazy" width="${options.width||375}" height="${options.height||(name.startsWith('support-')?816:812)}">${options.chrome?ozonChrome():''}${options.mask?'<span class="skeleton-pulse" aria-hidden="true"></span>':''}</span></button>`;
