function header(){return `<a class="skip" href="#main">${t('К содержанию','Skip to content')}</a><div class="header-shell"><header class="header wrap"><a class="wordmark" href="${href('index.html')}" aria-label="${t('Люда Запевалова — главная','Lyudmila Zapevalova — home')}"><span class="avatar" aria-hidden="true"><span class="avatar-clip"><img src="assets/lyudmila-portrait.jpeg" alt="" width="1010" height="1468"></span>${avatarFlower}</span><span class="brand-name">${t('Люда Запевалова','Lyudmila Zapevalova')}</span></a><nav class="nav" aria-label="${t('Основная навигация','Main navigation')}"><div class="nav-links"><a href="${href('index.html','#work')}">${t('Проекты','Projects')}</a><a href="${href('index.html','#about')}">${t('Обо мне','About')}</a><a href="#contact">${t('Связаться','Contact')}</a><a href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Резюме','CV')}</a></div><div class="languages" aria-label="${t('Язык сайта','Site language')}"><button data-lang="ru" aria-pressed="${lang==='ru'}">RU</button><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div></nav></header></div>`}
function footer(){return `<footer class="footer" id="contact"><div class="wrap"><div class="footer-main"><div><h2>${t('Открыта к новым<br>проектам и сотрудничеству.','Open to new projects<br>and collaboration.')}</h2><div class="contact-links"><a href="mailto:l.zapevalova@gmail.com">Email ${externalArrow}</a>${external('https://t.me/l_zapevalova','Telegram')}${external('https://www.behance.net/lyudazapevalova','Behance')}${external('https://www.linkedin.com/in/lyudmila-zapevalova/','LinkedIn')}<a href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Резюме','CV')} ${externalArrow}</a></div></div><a class="text-link" href="#top">${t('Наверх','Back to top')} ↑</a></div><div class="footer-meta"><span>© 2026 ${t('Люда Запевалова','Lyudmila Zapevalova')}</span><span>${t('Алматы, Казахстан','Almaty, Kazakhstan')}</span></div></div></footer>`}
const works=[
['02','Иви','Ivi','Скачивание контента для просмотра офлайн','Download content to watch offline',null],
['03','Ozon','Ozon','Поиск и выбор товаров','Product discovery and shopping','https://www.behance.net/gallery/255222461/Ozon-Discovery-Experience-Mobile-E-commerce-Product'],
['04','Звук','Zvuk','Перенос музыки из других сервисов','Bring your music from other services','https://www.behance.net/gallery/255116613/Music-transfer-feature-for-Zvuk-streaming-app'],
['05','CinemaPark','CinemaPark','Редизайн сайта кинотеатра','Cinema website redesign','https://www.behance.net/gallery/244309843/redizajn-sajta-sinema-park-Website-redesign'],
['06','Plate Planner','Plate Planner','Планирование питания и покупок','Meal planning and grocery shopping','https://www.behance.net/gallery/253168279/Meal-Planning-Grocery-Shopping-UXUI-Case-Study']];
function caseNavigation(currentName){
  const pages={"Иви":"ivi.html",Finelo:'finelo.html',Ozon:'ozon.html'};
  const cases=[['Finelo','Finelo'],...works.map(work=>[work[1],work[2]])];
  const index=cases.findIndex(item=>item[0]===currentName);
  const neighbours=[{item:cases[index-1],previous:true},{item:cases[index+1],previous:false}].filter(neighbour=>neighbour.item);
  return `<nav class="next-case-wrap case-pagination ${index===0?'case-pagination-single':''}" aria-label="${t('Другие кейсы','Other case studies')}">${neighbours.map(({item,previous})=>{
    const url=pages[item[0]]?href(pages[item[0]]):null,name=t(item[0],item[1]);
    const label=previous?t(`Перейти к предыдущему кейсу: ${name}`,`Go to the previous case study: ${name}`):t(`Перейти к следующему кейсу: ${name}`,`Go to the next case study: ${name}`);
    const arrow=`<svg class="next-case-arrow ${previous?'next-case-arrow-previous':''}" viewBox="0 0 24 20" fill="none" aria-hidden="true"><path d="M2 10h20m-6-6 6 6-6 6"/></svg>`;
    const compactLabel=previous?t(`Предыдущий кейс: ${name}`,`Previous case: ${name}`):t(`Следующий кейс: ${name}`,`Next case: ${name}`);
    const copy=`<span><span class="case-link-label-full">${label}</span><span class="case-link-label-compact">${compactLabel}</span></span>`;
    const contents=previous?`${arrow}${copy}`:`${copy}${arrow}`;
    const cards={Finelo:fineloCard,Иви:iviCard,Ozon:ozonCard};
    const preview=cards[item[0]]?`<span class="case-nav-preview" aria-hidden="true"><span class="case-preview-canvas">${cards[item[0]]().replace(/^<a /,'<span ').replace(/ href="[^"]*"/,'').replace(/<\/a>$/,'</span>')}</span></span>`:'';
    const className=`next-case ${previous?'case-previous':'case-next'}`;
    return url?`<a class="${className}" href="${url}">${contents}${preview}</a>`:`<button class="${className}" disabled title="${t('Кейс готовится','Case study coming soon')}">${contents}</button>`;
  }).join('')}</nav>`;
}
function workRow(w){if(w[1]==="Иви")return iviCard();if(w[1]==='Ozon')return ozonCard();return `<${w[5]?'a':'div'} class="work-row ${w[5]?'':'pending'}" ${w[5]?`href="${w[5]}" target="_blank" rel="noopener noreferrer"`:''}><span class="num">${w[0]}</span><h3>${t(w[1],w[2])}</h3><p>${t(w[3],w[4])}</p><span class="status">${t('Учебный проект','Study project')}<br>${w[5]?'Behance':t('Скоро в портфолио','Case study coming soon')}</span></${w[5]?'a':'div'}>`}
const skills=[['Figma','Figma'],['FigJam','FigJam'],['Notion','Notion'],['Miro','Miro'],['Pthwy','Pthwy'],['Principle','Principle'],['Прототипирование','Prototyping'],['Вайрфрейминг','Wireframing'],['Дизайн-системы','Design systems'],['UX-исследования','UX research'],['CustDev','CustDev'],['CJM','CJM'],['Мобильные интерфейсы','Mobile design'],['Веб-интерфейсы','Web design'],['Продуктовая аналитика','Product analytics'],['A/B-тестирование','A/B testing'],['Маркетинг','Marketing'],['Передача в разработку','Design handoff'],['Codex','Codex'],['Claude','Claude'],['Английский B2','English B2']];
