function fineloCard(){return `<a class="feature feature-finelo" href="${href('finelo.html')}"><div class="feature-copy"><div class="feature-tags"><span>B2C</span><span>EdTech</span><span>2026</span></div><h3>Finelo</h3><p class="feature-description">${t('Трейдинг и инвестиции:<br>от теории к практике','Trading and investing:<br>from theory to practice')}</p><p class="feature-platform">${t('Мобильное приложение и веб','Mobile app and web')}</p><p class="feature-scope">${t('Мой вклад — от исследований<br>до запуска и анализа результатов.','My work: from research<br>to launch and measuring results.')}</p></div><div class="feature-screens" aria-hidden="true">${['pathway','complete','practice'].map(cardPhone).join('')}</div></a>`;}
function home(){return `<main id="main" class="wrap"><section class="hero"><div class="eyebrow"><span class="dot"></span>${t('ПРОДУКТОВЫЙ ДИЗАЙНЕР · АЛМАТЫ','PRODUCT DESIGNER · ALMATY')}</div><h1>${t('Привет, я Люда.<br>Проектирую интерфейсы,<br> которые <em>легко понять.</em>','Hi, I’m Lyuda.<br>I design interfaces<br> that <em>make sense.</em>')}</h1>${flower}<div class="hero-bottom"><p>${t('Проектирую мобильные и веб-продукты: от первых вопросов пользователям до запуска и работы с результатами.','I design mobile and web products, from asking the first questions to shipping and learning from the results.')}</p></div></section><section id="work" aria-label="${t('Проекты','Projects')}">${fineloCard()}<div class="other-projects">${works.slice(0,3).map(workRow).join('')}</div></section><section class="web-works"><div class="section-top"><h2>${t('Ещё немного веба','A little more web')}</h2><span>${t('Интерфейсы для большого экрана','Designing for larger screens')}</span></div>${works.slice(3).map(workRow).join('')}</section><section id="about" class="about"><div class="about-title"><h2>${t('Немного<br>обо мне','A little<br>about me')}</h2><div class="about-art">${aboutIllustration}</div></div><div class="about-copy"><p>${t('Разбираюсь в задаче, задаю вопросы и проверяю гипотезы. Соединяю потребности людей, цели продукта и возможности разработки.','I get to the heart of a problem, ask questions and test hypotheses. I bring together people’s needs, product goals and engineering constraints.')}</p><p>${t('Внимательна к деталям: от текста на кнопке до состояний интерфейса. Беру ответственность за задачу и довожу решение до запуска вместе с командой.','I pay attention to details, from button copy to interface states. I take ownership of a task and work with the team to bring the solution to launch.')}</p><p>${t('В свободное время читаю, вяжу классные штуки, хожу в походы и катаюсь на горных лыжах, фанатею по вселенной Гарри Поттера.','Outside work, I read, knit fun things, hike and ski, and love the Harry Potter universe.')}</p><a class="text-link" href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Подробнее в резюме','Read my CV')} ${externalArrow}</a></div></section><section class="skills-section" id="skills"><div class="skills-heading"><h2>${t('Что я умею','What I bring')}</h2></div><ul class="skill-cloud">${skillOrder.map(i=>`<li class="skill-chip skill-${skillGroups[i]}" style="--tilt:${i%2===0?'-2':'2'}deg"><span>${t(...skills[i])}</span></li>`).join('')}</ul></section></main>`}
function caption(title,desc){return `<figcaption class="media-caption"><h3>${title}</h3><p>${desc}</p></figcaption>`}
function intro(num,title,desc=''){return `<div class="chapter-intro"><div class="chapter-index">${num}</div><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div></div>`}
function productCaption(title,desc){return `<figcaption class="product-caption"><h3>${title}</h3><p>${desc}</p></figcaption>`}
function caseResults(items){return `<div class="case-results"><h3>${t('Итоги','Outcomes')}</h3><ul>${items.map(([ru,en])=>`<li>${t(ru,en)}</li>`).join('')}</ul></div>`}
function finelo(){return `<main id="main" class="wrap"><a class="back" href="${href('index.html','#work')}"><svg class="back-arrow" viewBox="0 0 24 20" aria-hidden="true"><path d="M23 10H2m6-6-6 6 6 6"/></svg><span>${t('Все работы','All work')}</span></a><section class="case-head finelo-overview"><div class="case-summary"><div class="case-title-row"><h1>Finelo</h1><div class="case-external hover-links">${external('https://finelo.com',t('Сайт продукта','Product website'))}${external('https://apps.apple.com/si/app/finelo-master-trading/id6670422243','App Store')}</div></div><div class="case-tags"><span class="skill-chip skill-tools"><span>B2C</span></span><span class="skill-chip skill-design"><span>EdTech</span></span><span class="skill-chip skill-research"><span>Mobile & Web</span></span></div><p class="case-description">${t('Finelo — подписочное приложение для обучения инвестициям и трейдингу. Короткие уроки, практические задания и игровые механики помогают изучать основы и применять знания в виртуальном симуляторе. Основная аудитория — пользователи из США.','Finelo is a subscription app for learning investing and trading. Short lessons, practical exercises and game mechanics help users learn the basics and apply their knowledge in a virtual simulator. Its main audience is users in the US.')}</p><div class="case-facts"><div><span class="label">${t('Компания','Company')}</span><p>Zimran</p></div><div><span class="label">${t('Моя роль','My role')}</span><p>${t('Продуктовый дизайнер','Product Designer')}</p></div></div></div><aside class="team-card"><h2>${t('Команда продукта','Product team')}</h2><ul>${[['Продакт-менеджер','Product manager','1'],['Продуктовые дизайнеры','Product designers','4'],['Rive-аниматор','Rive animator','1'],['Learning дизайнеры','Learning Designers','4'],['Разработчики','Developers','8'],['Аналитик','Analyst','1']].map(([ru,en,count])=>`<li><span>${t(ru,en)}</span><span>${count}</span></li>`).join('')}</ul></aside></section><nav class="chapter-nav" aria-label="${t('Разделы кейса','Case sections')}"><div class="inner">${[['product','Как устроен Finelo','Inside Finelo'],['contribution','Мой вклад','My contribution'],['problems','Проблематика','The challenges'],['support','Доходимость до поддержки','Reaching support'],['webapp','Web → App','Web → App'],['upsells','Дополнения к подписке','Subscription add-ons'],['research','Исследования','Research'],['system','Дизайн-система','Design system']].map(([id,ru,en])=>`<a href="#${id}">${t(ru,en)}</a>`).join('')}</div></nav>
<section class="chapter product-overview" id="product"><h2 class="product-title">${t('Как устроен Finelo','Inside Finelo')}</h2><figure class="visual-block">${productCaption(t('Уроки и практика','Lessons and practice'),t('Пользователь последовательно изучает темы, а в конце каждой проходит проверочный квиз. Весь путь обучения виден на главном экране. Короткие объяснения чередуются с заданиями: сопоставить варианты ответов или выбрать покупку либо продажу по тренду на графике. После каждого задания пользователь сразу получает обратную связь.','Users work through topics in order and take a quiz at the end of each one. The home screen shows the entire learning path. Short explanations alternate with exercises: matching answers or choosing to buy or sell based on a chart trend. Users get immediate feedback after each task.'))}<div class="screen-stage mint">${screen('quiz','Задание в уроке','Lesson exercise')}${screen('practice','Покупка или продажа по тренду на графике','Buy or sell based on a chart trend')}${screen('feedback','Обратная связь после задания','Feedback after an exercise')}</div></figure><figure class="visual-block">${productCaption(t('Игровые механики','Game mechanics'),t('Награды за уроки, серии занятий и место в рейтинге помогают видеть прогресс и добавляют игровой интерес.','Lesson rewards, learning streaks and leaderboard progress bring a sense of achievement and play to the learning experience.'))}<div class="screen-stage peach">${screen('complete','Урок завершён','Lesson complete')}${screen('streak','Серия занятий','Learning streak')}${screen('leaderboard','Место в рейтинге','Leaderboard progress')}</div></figure><figure class="visual-block">${productCaption(t('Инструменты для практики','Tools for practice'),t('Виртуальный симулятор, AI-ментор, анализатор графиков и другие инструменты помогают применять знания на практике.','A virtual simulator, AI mentor, chart analyzer and other tools help users put their knowledge into practice.'))}<div class="screen-stage blue">${screen('tools','Инструменты для практики','Practice tools overview')}${screen('simulator','Виртуальный симулятор','Virtual trading simulator')}${screen('mentor','AI-ментор','AI mentor')}</div></figure></section>
<section class="chapter contribution-overview" id="contribution"><h2 class="section-title">${t('Мой вклад','My contribution')}</h2><p class="contribution-description">${t('Работала над переходом в приложение, онбордингом, поддержкой, дополнительными покупками и другими сценариями. Вела задачи от исследования до запуска: готовила макеты, описывала поведение и анимацию, проверяла реализацию. Вместе с разработчиками запускала тесты, собирала дашборды и следила за результатами.','I worked on the transition to the app, onboarding, support, add-ons and other flows. I owned tasks from research to launch: designed screens, documented interactions and motion, and checked the implementation. I ran tests with developers, built dashboards and tracked the results.')}</p><div class="work-gallery"><figure class="task-tile task-wide"><div class="task-stage blue">${screen('work-books','Магазин учебных материалов','Learning materials store')}${screen('work-book-details','Описание и покупка книги','Book details and purchase')}${screen('work-book-library','Книга добавлена в библиотеку','Book added to the library')}</div><figcaption><h3>${t('Магазин учебных материалов','Learning materials store')}</h3></figcaption></figure><figure class="task-tile"><div class="task-stage mint">${screen('work-force-update','Обязательное обновление приложения','Required app update')}${screen('work-soft-update','Предложение обновить приложение','Optional app update')}</div><figcaption><h3>${t('Обновление приложения','App updates')}</h3></figcaption></figure><figure class="task-tile task-wide"><div class="task-stage lavender">${screen('work-store-en','Стор-скрин на английском','English store screenshot')}${screen('work-store-fr','Стор-скрин на французском','French store screenshot')}${screen('work-store-ar','Стор-скрин на арабском','Arabic store screenshot')}</div><figcaption><h3>${t('Локализация и стор-скрины','Localization and store listings')}</h3></figcaption></figure><figure class="task-tile"><div class="task-stage yellow">${screen('work-welcome','Первый вход в приложение','First entry into the app')}</div><figcaption><h3>${t('Первый вход в приложение','First entry into the app')}</h3></figcaption></figure></div></section>
<section class="chapter problem-overview" id="problems"><h2 class="section-title">${t('Проблематика','The challenges')}</h2><p class="problem-intro">${t('Вот некоторые из продуктовых задач, над которыми я работала.','Here are some of the product challenges I worked on.')}</p><ul class="problem-list"><li>${t('После покупки часть пользователей так и не переходила из веба в мобильное приложение.','Some users dropped off after purchasing, before reaching the mobile app.')}</li><li>${t('Пользователям старшего возраста было сложнее разобраться, как начать пользоваться продуктом после покупки.','Older users were more likely to get lost when trying to start using the product after purchasing.')}</li><li>${t('Пользователи не всегда понимали предложения о дополнительных покупках.','Some users misunderstood the additional purchase offers.')}</li><li>${t('Ожидания от рекламы не всегда совпадали с тем, что пользователи видели в приложении.','Expectations set by ads did not always match the in-app experience.')}</li></ul></section>
<section class="chapter support-chapter" id="support"><h2 class="section-title">${t('Доходимость до поддержки','Reaching support')}</h2><div class="case-copy"><p>${t('Я инициировала задачу, когда заметила рост негативных отзывов в сторах и опросах CSAT. Одновременно росло число отписок. Появилась гипотеза: столкнувшись с проблемой, пользователи не находят поддержку и сразу идут отменять подписку.','I initiated this task after noticing more negative feedback in app stores and CSAT surveys, alongside a rise in cancellations. My hypothesis was that users who ran into a problem could not find support and went straight to cancel their subscription.')}</p><p>${t('В интервью пользователи рассказывали, что пропускали ответы поддержки: письма терялись в почте, хотя агент уже ответил.','In interviews, users said they missed support replies: emails got lost in their inboxes even though an agent had already responded.')}</p><p>${t('Я вынесла блок поддержки наверх в настройках и разделила пути. Со срочным вопросом можно было сразу обратиться к CX-агенту. Для самостоятельного поиска ответа оставила FAQ, а внутри — переход к агенту, если нужного ответа не нашлось.','I moved the support section to the top of settings and separated the paths. Users with urgent questions could reach a CX agent directly. The FAQ remained available for self-service, with a way to contact an agent if it did not answer their question.')}</p></div><div class="support-flow screen-stage mint"><figure>${screen('support-settings','Поддержка вверху настроек','Support at the top of settings')}<figcaption>${t('Поддержка в настройках','Support in settings')}</figcaption></figure><figure>${screen('support-faq','FAQ с переходом к агенту','FAQ with a way to reach an agent')}<figcaption>${t('FAQ и переход к агенту','FAQ and contact option')}</figcaption></figure><figure>${screen('support-request','Форма обращения в поддержку','Support request form')}<figcaption>${t('Форма обращения','Support request')}</figcaption></figure></div><div class="case-copy support-test"><p>${t('В тесте сравнили исходную версию с новой: обращений в поддержку стало больше. Сам по себе этот сигнал ещё не говорил об успехе, поэтому я дополнительно проверила отписки. В тестовой группе их стало заметно меньше. Версию раскатили на всех пользователей.','We compared the original and revised versions in an experiment. More users reached support, but that signal alone did not establish success, so I also checked cancellations. They were noticeably lower in the test group. The revised version was rolled out to all users.')}</p><p>${t('Эта задача показала мне, что даже небольшие изменения интерфейса могут дать заметный результат.','This task showed me that even small interface changes can make a meaningful difference.')}</p></div><div class="support-chat"><div class="case-copy"><h3>${t('Следующая итерация — чат в приложении','Next iteration: in-app chat')}</h3><p>${t('Следующим шагом я предложила заменить тикеты с ответом на почту чатом с CX-агентом прямо в приложении. Так пользователям было бы проще продолжать разговор и не терять ответы.','Next, I proposed replacing email-based tickets with a chat with a CX agent inside the app, so users could continue the conversation and keep track of replies.')}</p><p>${t('Столкнулась с техническими ограничениями: для запуска чата нужно было сократить время ответа агента до 3–5 минут. Во второй итерации это удалось сделать, и чат внедрили.','I encountered technical constraints: launching the chat required bringing agent response time down to 3–5 minutes. We achieved this in the second iteration and implemented the chat.')}</p></div><div class="screen-stage blue">${screen('support-chat','Чат с CX-агентом в приложении','In-app chat with a CX agent')}</div></div>${caseResults([['Рост обращений в поддержку','More users reaching support'],['Снижение отписок','Fewer cancellations']])}</section>
<section class="chapter" id="webapp"><div class="split-task"><div class="case-copy"><h2 class="section-title">Web → App</h2><p>${t('После покупки подписки часть пользователей не переходила в приложение и терялась на вебе. Особенно сложно этот шаг давался аудитории 55+.','After purchasing a subscription, some users did not make it to the app and got lost on the web. This step was especially difficult for users aged 55+.')}</p><p>${t('При этом мы готовили запуск пуш-кампании и хотели переводить покупки в приложение. Важно было помочь пользователям освоиться в нём: продолжать обучение, находить купленные материалы и возвращаться к занятиям по уведомлениям.','We were preparing to launch a push notification campaign and wanted to move purchases into the app. Users needed a clear way to get started there, continue learning, find their purchased materials and return to lessons through notifications.')}</p><p>${t('В прежнем экране одновременно конкурировали автоматический и ручной вход, несколько инструкций и видео. Пользователю приходилось разбираться, с чего начать.','The original screen presented automatic and manual login, several instructions and a video at once. Users had to figure out where to start.')}</p><p>${t('Я изучила воронку, провела ресерч и посмотрела решения конкурентов. Уменьшила визуальную нагрузку, выстроила понятную пошаговую инструкцию и упростила тексты. Оставила возможность продолжить в браузере.','I analyzed the funnel, carried out research and reviewed competitors. I reduced visual clutter, created a clear step-by-step guide and simplified the copy, while keeping the option to continue in the browser.')}</p></div><div class="screen-stage blue">${screen('webapp','Понятная инструкция для перехода в приложение','Clear instructions for moving to the app')}</div></div>${caseResults([['Рост активации приложения','Higher app activation'],['Запуск для всех возрастов','Rollout to all age groups']])}</section>
<section class="chapter" id="upsells"><h2 class="section-title">${t('Дополнения к подписке','Subscription add-ons')}</h2><div class="case-copy section-lead"><p>${t('Одновременно поступило много требований от комплаенса. Макеты были разрознены, часть экранов из продукта отсутствовала в Figma. Нужно было ясно показать, что дополнение оплачивается отдельно, и сохранить выручку от этих покупок.','Many compliance requirements arrived at once. Designs were scattered and some live screens were missing from Figma. We needed to make it clear that add-ons were separate purchases while preserving their revenue.')}</p><p>${t('В продукте было четыре направления: учебные челленджи по трейдингу и инвестициям, а также направления с ИИ-инструментами. Набор дополнений зависел от направления: от учебных материалов до инструментов, которые помогали вырабатывать и применять свою стратегию.','The product had four tracks: trading and investing learning challenges, plus tracks with AI tools. Add-ons varied by track, from learning materials to tools that helped users develop and apply their own strategies.')}</p></div><div class="screen-stage yellow upsell-stage">${screen('upsell-materials','Дополнение с AI Coach','AI Coach add-on',{crop:true})}${screen('upsell-trading','Учебное пособие по трейдингу с ИИ','AI trading guide',{crop:true})}${screen('upsell-mentor','Набор AI Coach и учебных материалов','AI Coach and learning materials bundle',{crop:true})}</div><div class="case-copy after-screens"><p>${t('Восстановила недостающие макеты и работала над переводами. Согласовала тексты, оформление и условия покупки для 15 локалей. Вместе с разработчиками проверяла, что после покупки пользователь получает нужные учебные материалы.','I rebuilt missing screens and worked on translations. I aligned wording, design and purchase terms across 15 locales. With developers, I checked that each purchase delivered the right learning materials.')}</p><p>${t('Переработала интерфейсы и UX-тексты по требованиям комплаенса. Вместе с разработчиком запускала тесты и следила за выручкой.','I revised the interfaces and UX copy to meet compliance requirements. I ran experiments with a developer and tracked revenue.')}</p><p>${t('Требования комплаенса учтены, языковые версии согласованы. ARPU апселлов — выручка на пользователя — не снизился. Отдельные варианты показали рост.','Compliance requirements were met and language versions aligned. Add-on ARPU — revenue per user — was maintained. Some variants showed an increase.')}</p></div>${caseResults([['Требования комплаенса учтены','Compliance requirements met'],['ARPU апселлов сохранён','Add-on ARPU maintained']])}</section>
<section class="chapter" id="research"><h2 class="section-title">${t('Исследования','Research')}</h2><div class="case-copy"><p>${t('Изначально искали новые маркетинговые каналы. Я самостоятельно подготовила и провела интервью с пользователями из США на английском, затем систематизировала результаты.','The original goal was to find new marketing channels. I independently prepared and conducted interviews in English with US users, then synthesized the findings.')}</p><p>${t('В интервью проявились и продуктовые трудности: ожидания от рекламы не всегда совпадали с опытом в приложении. Я составила список проблем, предложила гипотезы и презентовала выводы команде.','The interviews also revealed product problems: expectations set by ads did not always match the in-app experience. I compiled the problems, proposed hypotheses and presented the findings to the team.')}</p><p>${t('Для маркетинга собрала выводы о возможных каналах привлечения. Для продукта — гипотезы и точки роста, которые помогли наметить дальнейшие улучшения.','For marketing, I gathered findings about potential acquisition channels. For the product, I identified hypotheses and opportunities to guide further improvements.')}</p></div>${caseResults([['Выводы для маркетинга','Marketing findings'],['Продуктовые гипотезы','Product hypotheses'],['Точки роста продукта','Product opportunities']])}</section>
<section class="chapter" id="system"><h2 class="section-title">${t('Дизайн-система','Design system')}</h2><div class="case-copy section-lead"><p>${t('Подготовила скелетоны для основных разделов приложения. Добавила компоненты и цветовые токены в дизайн-систему, описала анимацию и правила использования для разработчиков.','I designed skeleton loading states for the main app sections, added components and color tokens to the design system, and documented motion and usage rules for developers.')}</p><p>${t('Кроме состояний загрузки, работала и с другими частями дизайн-системы: поддерживала компоненты и их использование в продуктовых сценариях.','Beyond loading states, I also worked on other parts of the design system, maintaining components and how they were used in product flows.')}</p></div><div class="screen-stage blue system-stage">${screen('skeleton','Скелетон симулятора','Simulator skeleton',{mask:'skeleton-mask.svg'})}${screen('simulator','Готовый интерфейс симулятора','Loaded simulator interface')}${screen('skeleton-mentor','Скелетон AI-чата','AI chat skeleton',{mask:'skeleton-mentor-mask.svg?v=13'})}${screen('mentor','Готовый интерфейс AI-чата','Loaded AI chat interface')}</div></section><div class="case-end"><h2>${t('Спасибо за внимание!','Thanks for reading!')}</h2><a class="text-link" href="mailto:l.zapevalova@gmail.com">${t('Написать мне','Get in touch')} ${externalArrow}</a></div>${caseNavigation('Finelo')}</main>`}

const ozonAssets={"ozon-home":[804,7286],"ozon-outfit":[804,3570],"ozon-kit-chip-selected":[112,64],"ozon-brand-products":[804,3244],"ozon-kit-chip":[112,64],"ozon-status":[804,100],"ozon-search-category":[740,536],"ozon-idea-skincare":[318,252],"ozon-kit-card":[396,782],"ozon-research-brands":[772,772],"ozon-search-start":[740,624],"ozon-brand":[804,1748],"ozon-kit-tabbar":[864,164],"ozon-research-related":[788,772],"ozon-kit-cart":[380,64],"ozon-proto-interesting":[804,1748],"ozon-kit-primary":[190,112],"ozon-kit-search-typing":[672,88],"ozon-tabbar":[804,164],"ozon-promo-block":[740,742],"ozon-proto-start":[740,652],"ozon-proto-category":[740,578],"ozon-proto-main":[804,7196],"ozon-kit-double":[192,112],"ozon-kit-follow":[304,64],"ozon-kit-following":[328,64],"ozon-brands":[804,4088],"ozon-search":[804,3128],"ozon-kit-secondary":[190,88],"ozon-outfits":[804,1748],"ozon-idea-hiking":[318,458],"ozon-kit-search-idle":[672,88],"ozon-similar":[804,1748],"ozon-proto-promo":[804,1748],"ozon-item":[804,5210],"ozon-proto-category-view":[804,3844],"ozon-proto-results":[756,2374],"ozon-kit-modal":[804,600]};
const ozonScreen=(name,ru,en,crop=false)=>screen(name,ru,en,{width:ozonAssets[name][0],height:ozonAssets[name][1],crop,cropRatio:402/874});
function ozonCard(){return `<a class="feature feature-ozon" href="${href('ozon.html')}"><div class="feature-copy"><div class="feature-tags"><span>Mobile</span><span>E-commerce</span><span>UX / UI</span></div><h3>Ozon</h3><p class="feature-description">${t('Поиск и выбор товаров на главной маркетплейса','Finding products from the marketplace homepage')}</p><p class="feature-scope">${t('Исследование, тест прототипа,<br>интерфейс и UI kit.','Research, prototype testing,<br>interface design and UI kit.')}</p></div><div class="feature-screens card-device-screens" aria-hidden="true">${['ozon-home-preview-0','ozon-search-preview-0','ozon-outfits'].map(cardPhone).join('')}</div></a>`}
const ozonConnector=`<svg class="ozon-connector" viewBox="0 0 24 48" fill="none" aria-hidden="true"><path d="M12 3V43m-3-5 3 5 3-5"/></svg>`;
const ozonDown=`<svg viewBox="0 0 20 24" fill="none" aria-hidden="true"><path d="M10 3v17m-5-5 5 5 5-5"/></svg>`;
function ozonResultMark(kind){return `<svg class="ozon-result-art ozon-mark-${kind}" viewBox="0 0 80 80" aria-hidden="true">${kind==='check'?'<path class="ozon-mark-line" d="M16 43Q24 50 32 58Q48 40 65 20"/>':'<path class="ozon-mark-line" d="M24 26C24 7 59 8 59 27C59 42 40 40 40 53"/><circle class="ozon-mark-dot" cx="40" cy="68" r="5"/>'}</svg>`;}
const ozonKitPiece=(name,width,ru,en)=>`<div class="ozon-kit-piece" style="--component-width:${width}px"><div class="ozon-kit-static ${name}" role="img" aria-label="${t(ru,en)}"><img src="assets/${name}.${name==='ozon-kit-card'?'svg':'png'}?v=25" alt="" width="${ozonAssets[name][0]}" height="${ozonAssets[name][1]}" loading="lazy"></div></div>`;
function ozon(){
  return `<main id="main" class="wrap ozon-case"><a class="back" href="${href('index.html','#work')}"><svg class="back-arrow" viewBox="0 0 24 20" aria-hidden="true"><path d="M23 10H2m6-6-6 6 6 6"/></svg><span>${t('Все работы','All work')}</span></a>
<section class="case-head ozon-intro"><div class="case-summary"><div class="case-title-row"><h1 class="case-wordmark-heading"><img class="case-wordmark" src="assets/ozon-wordmark.svg" alt="Ozon" width="752" height="165"></h1></div><div class="case-tags"><span>Mobile</span><span>E-commerce</span><span>UX / UI</span></div><p class="case-description">${t('Ozon — маркетплейс с товарами разных категорий. Я переработала главную мобильного приложения, чтобы помочь начать и продолжить выбор товаров.','Ozon is an online marketplace offering products across different categories. I redesigned its mobile app homepage to help people start choosing products and pick up where they left off.')}</p><div class="case-facts"><div><span class="label">${t('Моя роль','My role')}</span><p>Product Designer</p></div><div><span class="label">${t('Формат','Format')}</span><p>${t('Учебный проект по брифу Ozon<br>Bang Bang Education · Продуктовый дизайнер+','Course project based on an Ozon brief<br>Bang Bang Education · Product Designer+')}</p></div></div></div></section>
<div class="ozon-cover" aria-label="${t('Превью готового интерфейса','Final interface preview')}">${ozonScreen('ozon-home','Главная Ozon','Ozon homepage',true)}${ozonScreen('ozon-search','Выдача поиска','Search results',true)}${ozonScreen('ozon-outfits','Образы от стилиста','Stylist outfits')}</div>
<nav class="chapter-nav" aria-label="${t('Разделы кейса','Case sections')}"><div class="inner">${[['task','Задача','The brief'],['research','Исследования','Research'],['testing','Тестирование','Usability testing'],['interface','Интерфейс','Interface'],['kit','UI kit','UI kit'],['result','Результат','Outcome']].map(([id,ru,en])=>`<a href="#${id}">${t(ru,en)}</a>`).join('')}</div></nav>
<section class="chapter ozon-task" id="task"><h2 class="section-title">${t('Задача','The brief')}</h2><div class="case-copy"><p>${t('По брифу, пользователи терялись на главной и не понимали, с чего начать. Страница требовала много внимания и не учитывала их интересы. Нужно было переработать главную: сделать первый шаг понятнее и помочь быстрее начать выбор товаров.','According to the brief, people felt lost on the homepage and did not know where to start. It demanded too much attention and did not reflect their interests. The brief was to redesign it with a clearer first step and help people start choosing products sooner.')}</p></div><div class="ozon-signals"><p>${t('Сигналы из брифа','Signals from the brief')}</p><ul>${[['Низкий CTR лент','Low feed CTR'],['Частые изменения запросов','Frequent query changes'],['Снижение успешности поиска · SDR','Declining discovery success · SDR']].map(([ru,en])=>`<li>${ozonDown}<span>${t(ru,en)}</span></li>`).join('')}</ul></div></section>
<section class="chapter" id="research"><h2 class="section-title">${t('Исследования','Research')}</h2><div class="case-copy section-lead"><p>${t('Разобрала бриф и задала дополнительные вопросы заказчику. Сформулировала исследовательские вопросы и гипотезы, провела интервью и сравнила решения конкурентов. Выделила ключевые инсайты.','I reviewed the brief and asked the client follow-up questions. I defined research questions and hypotheses, interviewed users and compared competitor approaches. I identified the key insights.')}</p></div><div class="ozon-insight-cards">${[
['Без точного запроса нужен ориентир','People need a starting point without a precise query','Категории в поиске и тематические подборки, чтобы помочь начать выбор.','Search categories and themed collections to help people start choosing.','blue'],
['Важно понимать, почему показан товар','Recommendations need a clear reason','Подборки по просмотрам и покупкам с понятными названиями.','Collections based on browsing and purchases, with clear section names.','lilac'],
['Выбор продолжается в несколько заходов','Shopping can span several visits','История запросов для возврата к поиску, подписка на бренды — чтобы следить за новинками.','Search history to revisit a query, and brand follows to keep up with new arrivals.','pink']
].map(([ru,en,ideaRu,ideaEn,color])=>`<article class="ozon-insight-card ozon-${color}"><dl><dt>${t('Инсайт','Insight')}</dt><dd>${t(ru,en)}</dd><dt>${t('Идея','Idea')}</dt><dd>${t(ideaRu,ideaEn)}</dd></dl></article>`).join('')}</div><p class="case-copy ozon-ideation">${t('На основе инсайтов сделала HMW, выделила идеи и приоритизировала их по пользе для пользователя, ценности для бизнеса и сложности реализации. Выбранные идеи перенесла в прототип.','I used the insights to create HMW questions, generate ideas and prioritise them by user value, business value and implementation effort. I took the selected ideas into a prototype.')}</p></section>
<section class="chapter" id="testing"><h2 class="section-title">${t('Юзабилити-тестирование','Usability testing')}</h2><p class="case-copy section-lead">${t('Собрала работающий прототип, сформулировала гипотезы для проверки и подготовила сценарий тестирования. С несколькими участниками проверила, как они начинают выбор без точного запроса и понимают назначение блоков.','I built a working prototype, defined testing hypotheses and prepared a test script. With several participants, I checked how they start browsing without a precise query and understand the homepage sections.')}</p>
<div class="ozon-prototype"><div class="ozon-prototype-heading"><h3>${t('Переходы с главной','Paths from the homepage')}</h3></div><div class="ozon-prototype-map"><figure class="ozon-map-node ozon-map-main"><figcaption class="screen-caption">${t('Главная: категории и подборки','Homepage: categories and collections')}</figcaption>${screen('ozon-proto-main',t('Прототип: главная','Prototype: homepage'),t('Прототип: главная','Prototype: homepage'),{width:804,height:7196,crop:true,cropRatio:402/874,cropOffset:718/874,chrome:true})}</figure><span class="ozon-map-mobile-arrow">${ozonConnector}</span><figure class="ozon-map-node ozon-map-promo"><figcaption class="screen-caption">${t('Промо-подборка','Promotional collection')}</figcaption>${screen('ozon-proto-promo','Прототип: промо-подборка','Prototype: promotional collection',{width:804,height:1748})}</figure><span class="ozon-map-mobile-arrow">${ozonConnector}</span><figure class="ozon-map-node ozon-map-category"><figcaption class="screen-caption">${t('Категория товаров','Product category')}</figcaption>${screen('ozon-proto-category-view','Прототип: категория товаров','Prototype: product category',{width:804,height:3844,crop:true,cropRatio:402/874,chrome:true})}</figure><span class="ozon-map-mobile-arrow">${ozonConnector}</span><figure class="ozon-map-node ozon-map-interesting"><figcaption class="screen-caption">${t('Продолжение просмотра','Continue browsing')}</figcaption>${screen('ozon-proto-interesting','Прототип: продолжение просмотра','Prototype: continue browsing',{width:804,height:1748})}</figure><svg class="ozon-map-connections" fill="none" aria-hidden="true"></svg></div></div>
<p class="case-copy ozon-test-summary">${t('На прототипе проверила основные сценарии выбора товаров и понятность структуры главной.','I used the prototype to test the main product discovery flows and the clarity of the homepage structure.')}</p><div class="ozon-test-results"><article class="ozon-test-positive">${ozonResultMark('check')}<h3>${t('Что сработало','What worked')}</h3><p>${t('Главная помогала начать выбор без точного запроса. Основные сценарии были понятны участникам.','The homepage helped participants start browsing without a precise query. The main flows were clear to them.')}</p></article><article class="ozon-test-question">${ozonResultMark('question')}<h3>${t('Что было непонятно','What was unclear')}</h3><p>${t('Иерархия страницы и названия отдельных блоков требовали уточнения. Некоторые действия вызывали разные ожидания.','The page hierarchy and some section names needed clarification. Some actions created different expectations.')}</p></article></div></section>
<section class="chapter" id="interface"><h2 class="section-title">${t('Готовый интерфейс','Final interface')}</h2><p class="case-copy section-lead">${t('На главной выделила три задачи: начать поиск, найти идеи и вернуться к выбору. После теста доработала решение с учётом замечаний. Следующий шаг — проверить готовый интерфейс на реальном контенте.','I organised the homepage around three tasks: starting a search, finding inspiration and returning to product discovery. After testing, I refined the solution based on the feedback. The next step is to test the final interface with real content.')}</p><figure class="ozon-flow"><figcaption class="product-caption"><h3>${t('Поиск с уточнением','Narrowing the search')}</h3><p>${t('Добавила категории в поиск: можно постепенно сузить выбор и перейти к выдаче с фильтрами. История запросов помогает вернуться к прошлому поиску.','I added categories to search so people can narrow their options before opening filtered results. Search history makes it easy to return to an earlier query.')}</p></figcaption><div class="ozon-gallery ozon-blue ozon-search-gallery"><div class="ozon-search-steps">${ozonScreen('ozon-search-start','Поиск: выбор категории','Search: choose a category')}<span class="ozon-step-arrow">${ozonConnector}</span>${ozonScreen('ozon-search-category','Поиск: уточнение категории','Search: narrow the category')}</div>${ozonScreen('ozon-search','Выдача поиска','Search results',true)}${ozonScreen('ozon-item','Карточка товара','Product details',true)}</div></figure>
<figure class="ozon-flow"><figcaption class="product-caption"><h3>${t('Подборки для вдохновения','Collections for inspiration')}</h3><p>${t('Сделала упор на персональные подборки на основе просмотров и покупок. Также добавила тематические редакционные подборки для вдохновения.','I focused on personalised collections based on browsing and purchases. I also added themed editorial collections for inspiration.')}</p></figcaption><div class="ozon-gallery ozon-pink">${screen('ozon-home','Главная: промо-подборки','Homepage: promotional collections',{width:804,height:7286,crop:true,cropRatio:402/874,cropOffset:670/874,chrome:true})}${ozonScreen('ozon-outfits','Образы от стилиста','Stylist outfits')}${ozonScreen('ozon-outfit','Подборка «Ретроспорт»','Retro sport collection',true)}</div></figure>
<figure class="ozon-flow"><figcaption class="product-caption"><h3>${t('Возвращение к выбору','Picking up where you left off')}</h3><p>${t('Собрала похожие предложения и новинки любимых брендов. Из подборки брендов можно перейти к магазину и его ассортименту.','I brought together similar suggestions and new arrivals from favourite brands. People can open a brand and browse its range.')}</p></figcaption><div class="ozon-gallery ozon-lilac ozon-return-gallery">${ozonScreen('ozon-similar','Вы смотрели похожее','Similar to items you viewed')}${ozonScreen('ozon-brands','Новинки любимых брендов','New arrivals from favourite brands',true)}${ozonScreen('ozon-brand','Страница бренда','Brand page',true)}${ozonScreen('ozon-brand-products','Ассортимент бренда','Brand product range',true)}</div></figure></section>
<section class="chapter" id="kit"><h2 class="section-title">UI kit</h2><p class="case-copy section-lead">${t('Сама собрала карточки товаров, кнопки, поиск, фильтры и навигацию с их состояниями. Использовала общие компоненты во всех сценариях.','I built the UI kit myself: product cards, buttons, search, filters and navigation with their states. I reused these components across the flows.')}</p><div class="ozon-kit-board"><div class="ozon-kit-column"><div class="ozon-kit-panel ozon-blue"><h3>${t('Кнопки','Buttons')}</h3><div class="ozon-kit-pieces">${ozonKitPiece('ozon-kit-primary',95,'Основная кнопка','Primary button')}${ozonKitPiece('ozon-kit-double',96,'Кнопка с подписью','Button with subtitle')}${ozonKitPiece('ozon-kit-secondary',95,'Вторичная кнопка','Secondary button')}${ozonKitPiece('ozon-kit-cart',190,'Кнопка покупки','Cart button')}${ozonKitPiece('ozon-kit-follow',152,'Подписаться','Follow')}${ozonKitPiece('ozon-kit-following',164,'Вы подписаны','Following')}</div></div><div class="ozon-kit-panel ozon-lilac"><h3>${t('Поиск и фильтры','Search and filters')}</h3><div class="ozon-kit-pieces">${ozonKitPiece('ozon-kit-search-idle',336,'Поиск: подсказка','Search: placeholder')}${ozonKitPiece('ozon-kit-search-typing',336,'Поиск: ввод','Search: typing')}${ozonKitPiece('ozon-kit-chip',56,'Фильтр','Filter')}${ozonKitPiece('ozon-kit-chip-selected',56,'Выбранный фильтр','Selected filter')}</div></div></div><div class="ozon-kit-column"><div class="ozon-kit-panel ozon-pink"><h3>${t('Модальное окно','Modal')}</h3>${ozonKitPiece('ozon-kit-modal',402,'Скрыть рекомендацию','Hide recommendation')}</div><div class="ozon-kit-panel ozon-blue"><h3>${t('Навигация','Navigation')}</h3>${ozonKitPiece('ozon-kit-tabbar',432,'Таббар','Tab bar')}</div></div><div class="ozon-kit-panel ozon-lilac ozon-kit-product"><h3>${t('Карточка товара','Product card')}</h3>${ozonKitPiece('ozon-kit-card',198,'Карточка товара','Product card')}</div></div></section>
<section class="chapter" id="result"><h2 class="section-title">${t('Результат','Outcome')}</h2><div class="case-copy"><p>${t('Переработала главную вокруг трёх задач: начать поиск, найти идеи и вернуться к выбору. Для каждой предусмотрела свой вход — категории в поиске, персональные и тематические подборки, похожие предложения и новинки любимых брендов.','I redesigned the homepage around three goals: start searching, find inspiration and return to choosing. Each has its own entry point: search categories, personalised and themed collections, related offers and new arrivals from favourite brands.')}</p><p>${t('Проверка прототипа показала, что участники могли начать выбор без точного запроса, и помогла определить, где нужно уточнить структуру и названия. Итог работы — готовые макеты основных сценариев и UI kit с общими компонентами.','Prototype testing showed that participants could start choosing without a precise query and helped identify where the structure and section names needed refinement. The final deliverables are detailed designs for the core flows and a UI kit with shared components.')}</p></div></section>
<section class="ozon-next"><h2>${t('Если бы решение запускали в продукте','If this were going into production')}</h2><p>${t('Согласовала бы с командой размещение промо и сервисов. Затем проверила бы готовый интерфейс на реальном контенте. Если основные сценарии понятны, перешла бы к A/B-тесту по метрикам из брифа.','I would agree on promotional and service placements with the team. Then I would test the final interface with real content. Once the core flows were clear, I would run an A/B test using the metrics from the brief.')}</p></section>
<div class="case-end"><h2>${t('Спасибо за внимание!','Thanks for reading!')}</h2><a class="text-link" href="mailto:l.zapevalova@gmail.com">${t('Написать мне','Get in touch')} ${externalArrow}</a></div>${caseNavigation('Ozon')}</main>`;
}

const iviPrototypeUrl='https://www.figma.com/proto/zCYpvH5zpPqkJbDcQybCXy?node-id=234-43247&starting-point-node-id=234%3A43247&scaling=scale-down&content-scaling=fixed';
const iviScreen=(name,ru,en)=>screen(name,ru,en,{width:392,height:name==='ivi-settings'?846:name.startsWith('ivi-smart-')&&name!=='ivi-smart-downloads'&&name!=='ivi-smart-intro'?844:848}).replace('assets/ivi-series.png','assets/ivi-series-sharp.jpg');
const iviFigure=(name,ru,en)=>`<figure class="ivi-screen">${iviScreen(name,ru,en)}</figure>`;
const iviDevice=(name,ru,en)=>iviScreen(name,ru,en).replace('class="screen"','class="screen phone-mockup"').replace('<span class="screen-surface ','<span class="phone-depth" aria-hidden="true">'+Array.from({length:24},(_,i)=>`<span style="--depth:${(i+1)/24}"></span>`).join('')+'</span>'+phoneControls+'<span class="screen-surface phone-display ');
function iviCard(){return `<a class="feature feature-ozon feature-ivi" href="${href('ivi.html')}"><div class="feature-copy"><div class="feature-tags"><span>Mobile</span><span>Streaming</span><span>UX / UI</span></div><h3>${t('Иви','Ivi')}</h3><p class="feature-description">${t('Фильмы и сериалы<br>без интернета','Films and series<br>to watch offline')}</p><p class="feature-scope">${t('Анализ сценариев и конкурентов,<br>интерфейс, прототип и тестирование.','Flow and competitor analysis,<br>interface, prototype and testing.')}</p></div><div class="feature-screens card-device-screens" aria-hidden="true">${['ivi-downloads','ivi-season','ivi-smart-downloads'].map(cardPhone).join('')}</div></a>`;}
function ivi(){return `<main id="main" class="wrap ivi-case">
<a class="back" href="${href('index.html','#work')}"><svg class="back-arrow" viewBox="0 0 24 20" aria-hidden="true"><path d="M23 10H2m6-6-6 6 6 6"/></svg><span>${t('Все работы','All work')}</span></a>
<section class="case-head ivi-intro"><div class="case-summary"><h1 class="case-wordmark-heading"><span class="ivi-logo-badge"><img class="case-wordmark" src="assets/ivi-logo-source.svg" alt="${t('Иви','Ivi')}" width="55" height="40"></span></h1><div class="case-tags"><span>Mobile</span><span>Streaming</span><span>UX / UI</span></div><p class="case-description">${t('Иви — онлайн-кинотеатр. Я спроектировала сценарий загрузок: от подготовки контента к поездке до управления скачанными сериями.','Ivi is a streaming service. I designed the download experience, from preparing content for a trip to managing downloaded episodes.')}</p><div class="case-facts"><div><span class="label">${t('Моя роль','My role')}</span><p>Product Designer</p></div><div><span class="label">${t('Платформа','Platform')}</span><p>iOS</p></div><div><span class="label">${t('Формат','Format')}</span><p>${t('Учебный проект по брифу Иви<br>Bang Bang Education · Продуктовый дизайнер+','Course project based on an Ivi brief<br>Bang Bang Education · Product Designer+')}</p></div></div></div></section>
<div class="ivi-cover" aria-label="${t('Превью интерфейса Иви','Ivi interface preview')}">${[['ivi-series','Карточка сериала','Series page'],['ivi-season','Загрузка сезона','Season download'],['ivi-smart-settings','Настройки смарт-загрузок','Smart download settings']].map(([name,ru,en])=>`<figure class="ivi-cover-shot">${iviDevice(name,ru,en)}</figure>`).join('')}</div>
<nav class="chapter-nav" aria-label="${t('Разделы кейса','Case sections')}"><div class="inner">${[['task','Задача','The brief'],['analysis','Анализ','Analysis'],['interface','Интерфейс','Interface'],['prototype','Прототип','Prototype'],['testing','Проверка','Testing'],['result','Результат','Outcome']].map(([id,ru,en])=>`<a href="#${id}">${t(ru,en)}</a>`).join('')}</div></nav>
<section class="chapter ivi-task" id="task"><h2 class="section-title">${t('Задача','The brief')}</h2><div class="case-copy"><p>${t('В дороге и при нестабильном интернете скачанные фильмы и сериалы позволяют продолжать просмотр. По брифу, часть пользователей не знала о загрузках, а часть сталкивалась с неудобствами при их использовании.','Downloaded films and series keep people watching on the move or with an unreliable connection. According to the brief, some users did not know about downloads, while others found them inconvenient to use.')}</p><p>${t('Нужно было сделать функцию заметнее и проработать весь путь: выбрать контент, скачать, найти без сети и освободить место после просмотра. Бизнес-цели — увеличить использование загрузок и удержание зрителей сериалов.','The goal was to make downloads easier to notice and design the full journey: choosing content, downloading it, finding it offline and freeing space after watching. The business goals were to increase download usage and retain series viewers.')}</p></div></section>
<section class="chapter" id="analysis"><h2 class="section-title">${t('Анализ и гипотезы','Analysis and hypotheses')}</h2><div class="case-copy"><p>${t('Начала с разбора брифа: выделила бизнес-цели, контексты офлайн-просмотра и вопросы, на которые предстояло ответить. Изучила кейс-стади и UX-паттерны стриминговых сервисов — от знакомства с загрузками до управления просмотренным.','I started by analysing the brief: business goals, offline viewing contexts and questions to investigate. I studied case studies and UX patterns in streaming services, from discovering downloads to managing watched content.')}</p><p>${t('Прошла текущий путь в Иви и сравнила его с пятью сервисами: Кинопоиском, START, Amediateka, Netflix и Prime Video. Важными точками оказались знакомство с загрузками до потери сети и подготовка контента к следующему просмотру. Поэтому в приоритет поставила заметность функции, автоматизацию загрузки серий и управление просмотренным. Для каждой гипотезы определила метрики проверки.','I walked through the existing Ivi flow and compared it with five services: Kinopoisk, START, Amediateka, Netflix and Prime Video. The key moments were discovering downloads before losing connectivity and preparing content for the next viewing session. I prioritised making downloads easier to notice, automating episode downloads and managing watched content. I defined metrics for each hypothesis.')}</p></div><div class="ivi-notes"><table class="ivi-hypotheses-table"><colgroup><col><col></colgroup><thead><tr><th scope="col">${t('Продуктовая гипотеза','Product hypothesis')}</th><th scope="col">${t('Метрика','Metric')}</th></tr></thead><tbody>${[
['Заметность в подходящих точках и своевременное напоминание помогут чаще скачивать контент заранее.','Relevant entry points and timely reminders could help more people download content in advance.','Конверсия в первую загрузку; число пользователей загрузок.','First-download conversion; number of download users.'],
['Автозагрузка следующих серий и удаление просмотренных сократят действия при регулярном офлайн-просмотре.','Downloading next episodes and deleting watched ones automatically could reduce effort for regular offline viewing.','Число действий и время управления загрузками между просмотрами.','Number of actions and time spent managing downloads between viewing sessions.'],
['Статус просмотра и управление рядом с контентом помогут быстрее понять, что оставить, а что удалить.','Viewing status and contextual controls could make it easier to decide what to keep or remove.','Время управления библиотекой; успешность выполнения задачи.','Time spent managing the library; task success.']
].map(([ideaRu,ideaEn,metricRu,metricEn])=>`<tr class="ivi-hypothesis-row"><td><p>${t(ideaRu,ideaEn)}</p></td><td class="ivi-hypothesis-metric"><span class="ivi-metric-label" aria-hidden="true">${t('Метрика: ','Metric: ')}</span>${t(metricRu,metricEn)}</td></tr>`).join('')}</tbody></table></div><p class="case-copy ivi-after">${t('Взяла за основу брендовый UI kit Иви и добавила недостающие элементы и состояния. Проработала сценарии и связала экраны в интерактивный прототип.','I used the Ivi brand UI kit as a foundation and added missing elements and states. I designed the flows and connected the screens in an interactive prototype.')}</p></section>
<section class="chapter" id="interface"><h2 class="section-title">${t('Новый сценарий','The redesigned experience')}</h2>
<figure class="ivi-flow"><figcaption class="product-caption"><h3>${t('Подготовиться к просмотру без сети','Get ready to watch offline')}</h3><p>${t('Добавила вход в загрузки на главную и короткую подсказку при первом знакомстве. Качество видео и язык сохраняются для следующих загрузок. При выборе серий виден размер файлов — можно заранее оценить, сколько места они займут.','I added a homepage entry point and a short introduction to downloads. Video quality and language are saved for future downloads. File sizes are shown when choosing episodes, so people can estimate how much space they need.')}</p></figcaption><div class="ivi-gallery ivi-sky">${iviFigure('ivi-home-hint','Вход с главной','Homepage entry point')}${iviFigure('ivi-download-settings','Параметры для будущих загрузок','Preferences for future downloads')}${iviFigure('ivi-season','Сезон или отдельные серии','A season or individual episodes')}</div></figure>
<figure class="ivi-flow"><figcaption class="product-caption"><h3>${t('Найти скачанное и продолжить сериал','Find downloads and keep watching')}</h3><p>${t('Сохранила путь через «Моё». В списке серий показала прогресс просмотра и срок доступности. Предусмотрела настраиваемые напоминания о непросмотренных загрузках перед окончанием срока: в приложении и через push, если они разрешены. Кнопка «Загрузить ещё серии» ведёт сразу к выбору серий нужного сезона — без возврата в общую карточку сериала.','I kept the path through My Ivi. The episode list shows viewing progress and how long downloads remain available. I also designed optional reminders before unwatched downloads expire, in the app and via push when permitted. Download more episodes opens the relevant season directly, saving a return to the main series page.')}</p></figcaption><div class="ivi-gallery ivi-gallery-four ivi-lilac">${iviFigure('ivi-my','Скачанное в разделе «Моё»','Downloads in My Ivi')}${iviFigure('ivi-downloads','Все загрузки','All downloads')}${iviFigure('ivi-episodes','Прогресс и срок доступности','Progress and availability')}${iviFigure('ivi-next-episodes','Следующие серии','More episodes')}</div></figure>
<figure class="ivi-flow"><figcaption class="product-caption"><h3>${t('Управлять сериями и автоматическими загрузками','Manage episodes and automatic downloads')}</h3><p>${t('Предусмотрела предложение удалить просмотренное после выхода из плеера. В настройках можно выбрать, спрашивать об удалении или выполнять его автоматически.','I designed a prompt to delete watched episodes after leaving the player. People can choose whether the app asks before deleting or removes watched content automatically.')}</p></figcaption><div class="ivi-gallery ivi-gallery-pair ivi-sand">${iviFigure('ivi-delete','Удалить просмотренное','Delete watched episodes')}${iviFigure('ivi-settings','Выбрать поведение','Choose how deletion works')}</div><div class="ivi-smart-section"><p class="case-copy ivi-after">${t('Смарт-загрузки включают две возможности: скачивать следующую серию и подбирать контент по интересам. Пользователь задаёт лимит памяти и выбирает загрузку только по Wi-Fi. Рекомендации собраны отдельно в блоке «Загрузки для вас».','Smart downloads cover two features: downloading the next episode and selecting content based on interests. People set a storage limit and can restrict downloads to Wi-Fi. Recommendations appear separately under Downloads for you.')}</p><div class="ivi-gallery ivi-gallery-four ivi-mint ivi-smart-gallery">${iviFigure('ivi-smart-intro','Знакомство с функцией','Introducing smart downloads')}${iviFigure('ivi-smart-settings','Два вида автозагрузки','Two types of automatic download')}${iviFigure('ivi-smart-limit','Лимит памяти','Storage limit')}${iviFigure('ivi-smart-downloads','Загрузки для вас','Downloads for you')}</div></div></figure></section>
<section class="chapter" id="prototype"><h2 class="section-title">${t('Интерактивный прототип','Interactive prototype')}</h2><div class="ivi-prototype"><div class="ivi-prototype-heading"><h3>${t('Попробовать сценарий','Explore the flow')}</h3><span class="hover-links">${external(iviPrototypeUrl,t('Открыть в Figma','Open in Figma'))}</span></div><div class="ivi-prototype-stage" data-prototype-stage><img class="ivi-prototype-poster" src="assets/ivi-home.png" alt="${t('Главный экран Иви','Ivi home screen')}" width="392" height="848" loading="lazy"><div class="ivi-prototype-copy"><p>${t('От входа в загрузки до скачанного сезона. Пройдите путь в интерактивном прототипе.','From discovering downloads to saving a season. Try the journey in the interactive prototype.')}</p><div class="ivi-prototype-actions"><button class="ivi-prototype-start" data-load-prototype>${t('Запустить прототип','Launch prototype')} <svg viewBox="0 0 20 20" aria-hidden="true"><path d="m7 4 9 6-9 6Z"/></svg></button><a class="ivi-prototype-task" href="https://app.pthwy.ru/xXoqv" target="_blank" rel="noopener noreferrer">${t('Пройти задания в Pathway','Try the tasks in Pathway')} ${externalArrow}</a></div><p class="ivi-prototype-limits">${t('Независимо от выбранной карточки в прототипе открывается один и тот же сериал. Кликабельны только связанные со сценарием элементы, часть состояний упрощена. Скачивание условное, без ожидания; плеер и удаление отдельных серий работают с ограничениями.','Whichever content card is selected, the prototype opens the same series. Only elements within the flow are interactive, and some states are simplified. Downloads are simulated without waiting; player behaviour and individual episode deletion are limited.')}</p></div></div></div></section>
<section class="chapter" id="testing"><h2 class="section-title">${t('Проверка прототипа','Testing the prototype')}</h2><p class="case-copy section-lead">${t('На прототипе я проверяла понятность основных сценариев. Подготовила задания и провела немодерируемый тест в Pathway с 13 участниками. Они выполняли задания на компьютере и отвечали на вопросы после каждого сценария. Задания охватывали скачивание сезона, параметры, поиск сохранённого, смарт-загрузки и удаление просмотренной серии.','I used the prototype to test how clear the main flows were. I prepared tasks and ran an unmoderated Pathway test with 13 participants. They completed tasks on a computer and answered questions after each flow. The tasks covered season downloads, preferences, finding saved content, smart downloads and deleting watched episodes.')}</p>
<div class="ivi-test-results">${[
['12','оценили скачивание сезона как лёгкое или очень лёгкое','rated downloading a season easy or very easy'],
['11','нашли и включили смарт-загрузки','found and enabled smart downloads'],
['12','поняли или скорее поняли, почему появился автоматически подобранный контент','understood or mostly understood why automatically selected content appeared']
].map(([number,ru,en])=>`<article><div class="ivi-test-number">${number}<span>${t('из 13','of 13')}</span></div><p>${t(ru,en)}</p></article>`).join('')}</div>
<div class="case-copy ivi-after"><p>${t('С удалением возникли трудности: прототип не позволял удалить отдельную серию, а предложение удаления требовало условно досмотреть её и выйти. Эти ограничения повлияли на результат.','Deletion was difficult: the prototype did not support removing individual episodes, and the deletion prompt required participants to simulate watching an episode and leave the player. These limitations affected the results.')}</p></div></section>
<section class="chapter" id="result"><h2 class="section-title">${t('Результат и выводы','Outcome and learnings')}</h2><div class="case-copy"><p>${t('Связала разрозненные действия в один путь: заметить загрузки, подготовить сезон, найти скачанное и управлять библиотекой. Дополнила UI kit и собрала интерактивный прототип, который проверила на 13 участниках. После теста макеты сохранила без изменений.','I connected separate actions into one journey: discovering downloads, preparing a season, finding saved content and managing the library. I extended the UI kit and built an interactive prototype, tested with 13 participants. I kept the designs unchanged after testing.')}</p><p>${t('Главный вывод — проверять не только отдельные кнопки, но и весь цикл просмотра. В тесте особенно важно отделять ограничения прототипа от проблем интерфейса: затруднение ещё не объясняет его причину. Эта работа помогла связать аудит и приоритеты брифа с гипотезами, а результаты проверки — с вопросами для следующего исследования.','My main takeaway was to test the whole viewing cycle, as well as individual controls. During testing, it is essential to distinguish prototype limitations from interface problems: a difficulty alone does not explain its cause. This project helped me connect the audit and brief priorities to hypotheses, and test findings to questions for the next study.')}</p><p>${t('В следующем юзабилити-тесте отдельно проверю автозагрузку следующей серии и рекомендации по интересам. Результаты помогут определить, какие доработки нужны.','In the next usability test, I will test next-episode downloads and personalised recommendations as separate flows. The findings will help determine which improvements are needed.')}</p></div></section>
<div class="case-end"><h2>${t('Спасибо за внимание!','Thanks for reading!')}</h2><a class="text-link" href="mailto:l.zapevalova@gmail.com">${t('Написать мне','Get in touch')} ${externalArrow}</a></div>${caseNavigation('Иви')}</main>`;}
function bindIviPrototype(){
  const cover=document.querySelector('.ivi-cover');
  if(cover&&!matchMedia('(prefers-reduced-motion: reduce)').matches){iviCoverObserver=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){cover.classList.add('is-entering');cover.addEventListener('animationend',event=>{if(event.target.closest('.ivi-cover-shot')===cover.lastElementChild)cover.classList.remove('is-entering');});iviCoverObserver.disconnect();}},{threshold:.2});iviCoverObserver.observe(cover);}
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){
    iviHypothesesObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-revealed');iviHypothesesObserver.unobserve(entry.target);}});},{threshold:.4,rootMargin:'0px 0px -8% 0px'});
    document.querySelectorAll('.ivi-hypothesis-row').forEach(row=>{row.classList.add('will-reveal');iviHypothesesObserver.observe(row);});
  }
  const button=document.querySelector('[data-load-prototype]');
  button?.addEventListener('click',()=>{
    const stage=document.querySelector('[data-prototype-stage]'),iframe=document.createElement('iframe');
    iframe.src=`https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(iviPrototypeUrl)}`;
    iframe.title=t('Интерактивный прототип Иви — загрузка контента','Ivi interactive prototype — downloading content');iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';
    stage.classList.add('is-loaded');stage.replaceChildren(iframe);iframe.focus();
  });
}

function render(){iviCoverObserver?.disconnect();iviHypothesesObserver?.disconnect();if(stopFlowerMotion)stopFlowerMotion();if(chapterObserver)chapterObserver.disconnect();document.documentElement.lang=lang;document.title=isCase?`${isIvi?t('Иви','Ivi'):isOzon?'Ozon':'Finelo'} — ${t('Люда Запевалова','Lyudmila Zapevalova')}`:t('Люда Запевалова — Product Designer','Lyudmila Zapevalova — Product Designer');document.body.id='top';document.body.classList.toggle('case-page',isCase);document.getElementById('app').innerHTML=header()+(isIvi?ivi():isOzon?ozon():isCase?finelo():home())+footer()+`<dialog class="lightbox" aria-label="${t('Просмотр макета','Design preview')}"><button class="close">${t('Закрыть','Close')} ×</button><div class="preview-surface"><img alt=""><span class="skeleton-pulse" aria-hidden="true" hidden></span></div><p></p></dialog>`;bind();}
function bindFlowerMotion(){
  const cleanups=[...document.querySelectorAll('.flower,.about-flower')].map(flower=>{
  const petals=flower.querySelector('.flower-petals');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  let frame=0,angle=0,speed=0,previous=0,hovered=false;
  function tick(time){
    const dt=Math.min((time-previous)/1000,.05);previous=time;
    speed+=(hovered?180-speed:-speed)*(1-Math.exp(-dt*(hovered?7:3.8)));
    angle=(angle+speed*dt)%360;
    petals.setAttribute('transform',`rotate(${angle} 50 50)`);
    if(hovered||speed>.3)frame=requestAnimationFrame(tick);else{speed=0;frame=0;}
  }
  function start(){if(reduced.matches)return;hovered=true;if(!frame){previous=performance.now();frame=requestAnimationFrame(tick);}}
  function leave(){hovered=false;}
  function reset(){cancelAnimationFrame(frame);frame=0;speed=0;hovered=false;}
  flower.addEventListener('pointerenter',start);
  flower.addEventListener('pointerleave',leave);
  document.addEventListener('visibilitychange',reset);
  reduced.addEventListener('change',reset);
  return ()=>{reset();document.removeEventListener('visibilitychange',reset);reduced.removeEventListener('change',reset);};
  });
  stopFlowerMotion=()=>cleanups.forEach(cleanup=>cleanup());
}
function bind(){bindFlowerMotion();if(isIvi)bindIviPrototype();if(isOzon)bindOzonMap();document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{const y=scrollY;lang=b.dataset.lang;const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState({},'',u);render();scrollTo(0,y)}));const dlg=document.querySelector('dialog'),previewSurface=dlg.querySelector('.preview-surface');let sourceImage=null,closingPreview=false,previewAnimation=null;
const previewMotion=()=>!matchMedia('(prefers-reduced-motion: reduce)').matches;
function previewTransform(from,to){return `translate(${from.left-to.left}px,${from.top-to.top}px) scale(${from.width/to.width},${from.height/to.height})`;}
async function closeProductPreview(){
  if(closingPreview||!dlg.open)return;closingPreview=true;
  const im=dlg.querySelector('img');
  if(previewAnimation){try{await previewAnimation.finished;}catch{}previewAnimation=null;}
  dlg.classList.add('is-closing');
  if(sourceImage&&sourceImage.isConnected&&previewMotion()){
    const to=sourceImage.getBoundingClientRect(),from=previewSurface.getBoundingClientRect();
    try{await previewSurface.animate([{transform:'none',opacity:1},{transform:previewTransform(to,from),opacity:1}],{duration:320,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'}).finished;}catch{}
  }
  if(sourceImage){sourceImage.style.visibility='';sourceImage.closest('button').classList.add('preview-return-focus');}
  dlg.close();closingPreview=false;
}
document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',async()=>{
  const im=dlg.querySelector('img'),product=!!b.closest('.chapter,.ozon-cover,.ivi-cover');
  dlg.classList.remove('is-closing');dlg.classList.toggle('product-preview',product);
  previewSurface.getAnimations().forEach(a=>a.cancel());im.src=b.dataset.fullSrc||b.querySelector('img').src;im.alt=b.dataset.caption;
  dlg.querySelector('p').textContent=product?`${b.dataset.caption} · ${t('Нажми вне картинки, чтобы закрыть','Click outside the image to close')}`:b.dataset.caption;
  dlg.classList.toggle('mobile-image',!['purchases','localization'].includes(b.dataset.image));
  sourceImage=product?b.querySelector('.screen-surface'):null;
  if(product){try{await im.decode();}catch{}}
  const cropped=b.dataset.crop==='true',mask=b.dataset.skeletonMask;
  previewSurface.classList.toggle('is-cropped',cropped);
  previewSurface.classList.toggle('component-surface',b.dataset.component==='true');
  previewSurface.style.setProperty('--crop-offset',b.dataset.cropOffset||0);
  previewSurface.querySelectorAll('.screen-chrome').forEach(node=>node.remove());
  if(b.dataset.chrome==='true')previewSurface.insertAdjacentHTML('beforeend',ozonChrome());
  previewSurface.style.setProperty('--preview-ratio',cropped?(Number(b.dataset.cropRatio)||375/812):im.naturalWidth/im.naturalHeight);
  previewSurface.style.setProperty('--preview-natural-width',`${im.naturalWidth}px`);
  previewSurface.style.setProperty('--skeleton-mask',mask?`url(assets/${mask})`:'none');
  previewSurface.querySelector('.skeleton-pulse').hidden=!mask;
  const from=sourceImage?.getBoundingClientRect();dlg.showModal();document.body.style.overflow='hidden';
  if(product){dlg.setAttribute('tabindex','-1');dlg.focus({preventScroll:true});sourceImage.style.visibility='hidden';sourceImage.closest('button').classList.add('preview-source');
    if(previewMotion())previewAnimation=previewSurface.animate([{transform:previewTransform(from,previewSurface.getBoundingClientRect())},{transform:'none'}],{duration:360,easing:'cubic-bezier(.4,0,.2,1)'});
  }
}));
dlg.querySelector('.close').addEventListener('click',()=>dlg.close());
dlg.addEventListener('cancel',e=>{if(dlg.classList.contains('product-preview')){e.preventDefault();closeProductPreview();}});
dlg.addEventListener('click',e=>{if(dlg.classList.contains('product-preview')){if(!previewSurface.contains(e.target))closeProductPreview();return;}if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dlg.close();}});
document.querySelectorAll('.screen').forEach(button=>{['keydown'].forEach(event=>button.addEventListener(event,()=>button.classList.remove('preview-return-focus')));});
dlg.addEventListener('close',()=>{document.body.style.overflow='';if(sourceImage){sourceImage.style.visibility='';const sourceButton=sourceImage.closest('button');sourceButton.classList.remove('preview-source');sourceButton.focus({preventScroll:true});sourceButton.classList.add('preview-return-focus');sourceImage=null;}previewSurface.getAnimations().forEach(a=>a.cancel());});if(isCase)bindChapterNavigation();}
function bindChapterNavigation(){
  const sections=[...document.querySelectorAll('.chapter')],links=[...document.querySelectorAll('.chapter-nav a')];
  let pendingSection=null,frame=0,settleTimer=0;
  function selectSection(id){links.forEach(link=>{const active=link.hash==='#'+id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}
  function update(){
    frame=0;if(pendingSection){selectSection(pendingSection);return;}
    const threshold=document.querySelector('.header-shell').getBoundingClientRect().height+document.querySelector('.chapter-nav').getBoundingClientRect().height+24;
    let current=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=threshold)current=section;else break;}
    if(current)selectSection(current.id);
  }
  function schedule(){if(!frame)frame=requestAnimationFrame(update);}
  function settle(){pendingSection=null;schedule();}
  function onScroll(){schedule();clearTimeout(settleTimer);if(pendingSection)settleTimer=setTimeout(settle,180);}
  const onClick=event=>{pendingSection=event.currentTarget.hash.slice(1);selectSection(pendingSection);clearTimeout(settleTimer);settleTimer=setTimeout(settle,180);};
  const onManualScroll=()=>{pendingSection=null;clearTimeout(settleTimer);schedule();};
  links.forEach(link=>link.addEventListener('click',onClick));
  window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',schedule);window.addEventListener('wheel',onManualScroll,{passive:true});window.addEventListener('touchstart',onManualScroll,{passive:true});
  chapterObserver={disconnect(){cancelAnimationFrame(frame);clearTimeout(settleTimer);links.forEach(link=>link.removeEventListener('click',onClick));window.removeEventListener('scroll',onScroll);window.removeEventListener('resize',schedule);window.removeEventListener('wheel',onManualScroll);window.removeEventListener('touchstart',onManualScroll);}};
  update();
}

render();

var ozonMapObserver;
function bindOzonMap(){
  if(ozonMapObserver)ozonMapObserver.disconnect();
  const map=document.querySelector('.ozon-prototype-map'),svg=map.querySelector('svg.ozon-map-connections');
  const mainSurface=map.querySelector('.ozon-map-main .screen-surface');
  // Actual block bounds in the 804 × 1748 homepage viewport (crop at y=1436).
  const regions={category:[254,204,190,96],promo:[32,348,318,252],history:[32,1152,740,58]};
  Object.entries(regions).forEach(([name,[x,y,width,height]])=>{
    const region=document.createElement('span');
    region.dataset.prototypeRegion=name;region.setAttribute('aria-hidden','true');
    Object.assign(region.style,{position:'absolute',left:`${x/804*100}%`,top:`${y/1748*100}%`,width:`${width/804*100}%`,height:`${height/1748*100}%`,pointerEvents:'none'});
    mainSurface.append(region);
  });
  function draw(){
    if(!map.isConnected)return;
    const bounds=map.getBoundingClientRect();
    const rect=element=>{const r=element.getBoundingClientRect();return {x:r.left-bounds.left,y:r.top-bounds.top,w:r.width,h:r.height};};
    const viewport=name=>rect(map.querySelector(`.ozon-map-${name} .screen-surface`));
    const block=name=>rect(mainSurface.querySelector(`[data-prototype-region="${name}"]`));
    const main=viewport('main'),promo=viewport('promo'),category=viewport('category'),viewed=viewport('interesting');
    const kids=block('category'),collection=block('promo'),history=block('history');
    const gutter=Math.min(12,(category.x-main.x-main.w)*.4),laneX=main.x+main.w+gutter;
    const roundedPath=points=>{
      points=points.filter((point,index)=>index===0||Math.hypot(point.x-points[index-1].x,point.y-points[index-1].y)>.01);
      let d=`M${points[0].x} ${points[0].y}`;
      for(let i=1;i<points.length-1;i++){
        const a=points[i-1],b=points[i],c=points[i+1],ab=Math.hypot(b.x-a.x,b.y-a.y),bc=Math.hypot(c.x-b.x,c.y-b.y),radius=Math.min(8,ab/2,bc/2);
        const before={x:b.x+(a.x-b.x)*radius/ab,y:b.y+(a.y-b.y)*radius/ab},after={x:b.x+(c.x-b.x)*radius/bc,y:b.y+(c.y-b.y)*radius/bc};
        d+=`L${before.x} ${before.y}Q${b.x} ${b.y} ${after.x} ${after.y}`;
      }
      const end=points[points.length-1],previous=points[points.length-2],length=Math.hypot(end.x-previous.x,end.y-previous.y),dx=(end.x-previous.x)/length,dy=(end.y-previous.y)/length;
      return d+`L${end.x} ${end.y}M${end.x-dx*5-dy*3} ${end.y-dy*5+dx*3}L${end.x} ${end.y}L${end.x-dx*5+dy*3} ${end.y-dy*5-dx*3}`;
    };
    const categoryStart={x:kids.x+kids.w/2,y:kids.y+kids.h},categoryLane=main.y+main.h*324/1748;
    const categoryEnd={x:category.x-5,y:category.y+category.h*.22};
    const categoryPoints=[categoryStart,{x:categoryStart.x,y:categoryLane},{x:laneX,y:categoryLane},{x:laneX,y:categoryEnd.y},categoryEnd];
    const promoStart={x:collection.x,y:collection.y+collection.h/2},historyStart={x:history.x+history.w,y:history.y+history.h/2};
    let promoPoints,historyPoints;
    if(promo.x<main.x){
      const promoEnd={x:promo.x+promo.w+5,y:promo.y+promo.h*.30},leftLane=main.x-gutter;
      promoPoints=[promoStart,{x:leftLane,y:promoStart.y},{x:leftLane,y:promoEnd.y},promoEnd];
      const bottom=Math.max(main.y+main.h,category.y+category.h,viewed.y+viewed.h)+28,end={x:viewed.x+viewed.w/2,y:viewed.y+viewed.h+5};
      historyPoints=[historyStart,{x:laneX,y:historyStart.y},{x:laneX,y:bottom},{x:end.x,y:bottom},end];
    }else{
      const leftLane=main.x-gutter,promoEnd={x:promo.x-5,y:promo.y+promo.h*.30},historyEnd={x:viewed.x-5,y:viewed.y+viewed.h*.14};
      promoPoints=[promoStart,{x:leftLane,y:promoStart.y},{x:leftLane,y:promoEnd.y},promoEnd];
      historyPoints=[historyStart,{x:laneX,y:historyStart.y},{x:laneX,y:historyEnd.y},historyEnd];
    }
    svg.setAttribute('viewBox',`0 0 ${bounds.width} ${bounds.height}`);
    svg.innerHTML=[['category',categoryPoints],['promo',promoPoints],['history',historyPoints]].map(([name,points])=>`<path data-source-region="${name}" d="${roundedPath(points)}"/>`).join('');
  }
  ozonMapObserver=new ResizeObserver(draw);
  [map,...map.querySelectorAll('.screen-surface,figcaption')].forEach(element=>ozonMapObserver.observe(element));
  requestAnimationFrame(draw);document.fonts.ready.then(draw);
}
